#define GFS_CURVED_ORIGINAL_ORACLE_LIBRARY
#include "test_curved_original_oracle_v1.cpp"
#include "material_target_general.h"
#include <fstream>
#include <iomanip>
namespace tg=material_target_general;namespace ti=material_target_inverse;using S=mf::B<Q>;
static std::string qs(Q x){char s[128];quadmath_snprintf(s,sizeof(s),"%.36Qg",x);return s;}
int main(int argc,char**argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==6,"original packet sites guard new-output 225|137");size_t it=atoi(argv[5]);need(it==225||it==137,"same two physical controls only");auto p=curved::read(argv[1]);auto sites=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],sites);std::string dest=argv[4];const auto&r=p.record[it];Q anchor[2]={},origin[2]={};for(int k=0;k<2;k++){S center;for(int a=0;a<3;a++)center=center+S(Q(r.triangle.geometry.x[a][k]))/S(3);anchor[k]=center.n;}auto map=tg::compile(r,anchor,p.parameters[3]);auto started=std::chrono::steady_clock::now();
    curved_bounds::Tri tri;S box[2];for(int k=0;k<2;k++){Q lo=Q(r.triangle.geometry.x[0][k]),hi=lo;for(int a=0;a<3;a++){lo=std::min(lo,Q(r.triangle.geometry.x[a][k]));hi=std::max(hi,Q(r.triangle.geometry.x[a][k]));tri[a][k]=r.triangle.geometry.x[a][k];}S center=(S(lo)+S(hi))/S(2),width=(S(hi)-S(lo))/S(2);box[k]=S(center.n,ti::add(center.e,ti::mag(width)));}
    auto bound=positive_source_bounds(r,tri,p.parameters[3]);int own=-1;for(size_t j=0;j<sites.size();j++)if(sites[j].id==r.cell)own=j;need(own>=0,"physical owner");auto possible=source_candidates(r,bound,sites,weights,own);auto range=tg::evaluate<Q>(map,box[0],box[1]);Q global_L=0;for(int i=0;i<2;i++){Q row=0;for(int j=0;j<2;j++)row=ti::add(row,ti::mag(range.F[2*i+j]-S(i==j?1:0)));global_L=std::max(global_L,row);}need(global_L<1,"original nonzero-residual source globally injective on its box");for(int k=0;k<2;k++)origin[k]=tg::evaluate<Q>(map,S(anchor[0]),S(anchor[1])).position[k].n;
    std::ofstream roots(dest+"/source_edge_roots.csv"),segments(dest+"/source_edge_segments.csv"),queries(dest+"/boundary_queries.csv");roots<<"target,edge,competitor,t,t_radius,physical_x,physical_y,physical_x_radius,physical_y_radius\n";segments<<"target,edge,lo,lo_radius,hi,hi_radius,midpoint_strictly_inside_target,unclassified\n";queries<<"target,edge,kind,reference_x,reference_y,physical_x,physical_y,position_oracle_error,position_native_forward_radius,inverse_radius,inverse_global_L,inverse_inside_source,inverse_outside_source\n";
    uint64_t root_evaluations=0,nroots=0,inverse_queries=0,oracle_checks=0,oracle_excess=0,failed_root_contracts=0,unknown_segments=0;Q max_original_error=0,max_native_radius=0,max_inverse_radius=0;
    auto query=[&](int target,int edge,const char*kind,S X,S Y){auto exact=mf::original_at(r,X,Y,p.parameters[3]);auto compiled=tg::evaluate<Q>(map,X,Y);auto native=tg::evaluate<R>(map,X,Y);auto a=fields(exact),b=fields(compiled);auto c=fields(native);for(int k=0;k<13;k++){Q error=fabsq(b[k].n-a[k].n);if(error>mf::FP<Q>::up(b[k].e+a[k].e))oracle_excess++;error=fabsq(Q(c[k].n)-a[k].n);if(error>mf::FP<Q>::up(Q(c[k].e)+a[k].e))oracle_excess++;oracle_checks+=2;}Q error=std::max(fabsq(Q(native.position[0].n)-exact.position[0].n),fabsq(Q(native.position[1].n)-exact.position[1].n)),radius=std::max(Q(native.position[0].e),Q(native.position[1].e));max_original_error=std::max(max_original_error,error);max_native_radius=std::max(max_native_radius,radius);auto inverse=tg::inverse(map,r,compiled.position[0],compiled.position[1]);need(fabsq(inverse.X.n-X.n)<=ti::add(inverse.X.e,X.e)&&fabsq(inverse.Y.n-Y.n)<=ti::add(inverse.Y.e,Y.e),"same original source boundary inverse contains initial reference point");inverse_queries++;max_inverse_radius=std::max(max_inverse_radius,inverse.radius);queries<<sites[target].id<<','<<edge<<','<<kind<<','<<qs(X.n)<<','<<qs(Y.n)<<','<<qs(compiled.position[0].n)<<','<<qs(compiled.position[1].n)<<','<<qs(error)<<','<<qs(radius)<<','<<qs(inverse.radius)<<','<<qs(inverse.global_L)<<','<<inverse.inside<<','<<inverse.outside<<'\n';};
    for(int target:possible)if(target!=own){std::vector<tg::Plane> planes;for(int j=0;j<int(sites.size());j++)if(j!=target)planes.push_back(tg::plane(sites,weights,target,j,origin));for(int edge=0;edge<3;edge++){std::vector<tg::Root> cuts={{S(0),-1},{S(1),-1}};for(size_t ip=0;ip<planes.size();ip++){auto isolated=tg::roots(map,r,edge,planes[ip],origin,ip);root_evaluations+=isolated.evaluations;if(!isolated.complete){failed_root_contracts++;continue;}for(auto root:isolated.root){cuts.push_back(root);auto point=tg::edge(map,r,edge,root.t);roots<<sites[target].id<<','<<edge<<','<<sites[planes[ip].competitor].id<<','<<qs(root.t.n)<<','<<qs(root.t.e)<<','<<qs(point.x[0].n)<<','<<qs(point.x[1].n)<<','<<qs(point.x[0].e)<<','<<qs(point.x[1].e)<<'\n';nroots++;query(target,edge,"intersection",point.X,point.Y);}}
            std::sort(cuts.begin(),cuts.end(),[](const tg::Root&a,const tg::Root&b){return a.t.n<b.t.n;});for(size_t k=0;k+1<cuts.size();k++){S t=(cuts[k].t+cuts[k+1].t)/S(2);auto point=tg::edge(map,r,edge,S(t.n));bool inside=true,outside=false;for(auto&plane:planes){auto f=tg::value(plane,point.x[0],point.x[1],origin);inside=inside&&ti::upper(f)<0;outside=outside||ti::lower(f)>0;}bool unknown=!inside&&!outside;unknown_segments+=unknown;segments<<sites[target].id<<','<<edge<<','<<qs(cuts[k].t.n)<<','<<qs(cuts[k].t.e)<<','<<qs(cuts[k+1].t.n)<<','<<qs(cuts[k+1].t.e)<<','<<inside<<','<<unknown<<'\n';query(target,edge,"segment_midpoint",point.X,point.Y);}}
    }roots.close();segments.close();queries.close();bool geometry_pass=!failed_root_contracts&&!unknown_segments&&!oracle_excess;
    std::ofstream certificate(dest+"/source_certificate.json");certificate<<"{\"triangle\":"<<it<<",\"source\":"<<r.cell<<",\"P3_plus_initial_v0_residual\":true,\"original_coefficient_reference\":true,\"whole_source_box_J_lower\":\""<<qs(ti::lower(range.J))<<"\",\"whole_source_Linf_chi_minus_I\":\""<<qs(global_L)<<"\",\"max_native_original_position_error\":\""<<qs(max_original_error)<<"\",\"max_native_position_radius\":\""<<qs(max_native_radius)<<"\",\"max_inverse_radius\":\""<<qs(max_inverse_radius)<<"\"}";certificate.close();
    printf("{\"scope\":\"same physical225/137 nonzero-residual source; original-function native FMA evaluator, certified source edge/target-plane cuts and inverse; no polar-ray call or state update\",\"triangle\":%zu,\"source\":%llu,\"possible_targets\":%zu,\"root_evaluations\":%llu,\"edge_plane_intersections\":%llu,\"inverse_queries\":%llu,\"original_oracle_checks\":%llu,\"oracle_excess\":%llu,\"incomplete_root_contracts\":%llu,\"unclassified_boundary_segments\":%llu,\"source_boundary_arrangement_pass\":%s,\"positive_target_quadrature_complete\":false,\"source_gluing_and_quadrature_remainder_complete\":false,\"full_cold_transfer_proved\":false,\"seconds\":%.17g}\n",it,(unsigned long long)r.cell,possible.size(),(unsigned long long)root_evaluations,(unsigned long long)nroots,(unsigned long long)inverse_queries,(unsigned long long)oracle_checks,(unsigned long long)oracle_excess,(unsigned long long)failed_root_contracts,(unsigned long long)unknown_segments,geometry_pass?"true":"false",std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count());active_mpi=false;MPI_Finalize();return geometry_pass?0:2;
}
